private void checkForTimedOutUsers() {
  if (USER_IDLE == -1) {
    return;
  }
  final long deadline = System.currentTimeMillis() - USER_IDLE;
  for (MUCUser user : users.values()) {
    try {
      if (user.getLastPacketTime() < deadline) {
        Iterator<MUCRole> roles = user.getRoles();
        MUCRole role;
        MUCRoom room;
        Presence kickedPresence;
        while (roles.hasNext()) {
          role = roles.next();
          room = role.getChatRoom();
          try {
            kickedPresence = room.kickOccupant(user.getAddress().toStringPrep(), null, null);
            room.send(kickedPresence);
          } catch (NotAllowedException e) {
          } catch (UnauthorizedException e) {
          }
        }
      }
    } catch (NullPointerException | UnsupportedOperationException | ClassCastException | IllegalArgumentException e) {
      Log.error(LocaleUtils.getLocalizedString("admin.error"), e);
    }
  }
}
